1	export type Item = {
2	  type: string;
3	};
4	
5	export type QuoteStep = {
6	  op: "quote";
7	  items: Item[];
8	};
9	
10	export type Scenario = {
11	  customer: { yearsWithMHPCO: number };
12	  steps: QuoteStep[];
13	};
14	
15	export type ScenarioResults = {
16	  results: unknown[];
17	};
18	
19	const PROCESSING_FEE = 5;
20	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const policyBasePremium = (items: Item[]): number =>
32	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
33	
34	/** Premiums are rounded in the MHPCO's favour, i.e. up. */
35	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
36	
37	/**
38	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
39	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
40	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
41	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
42	 */
43	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
44	
45	const quote = (step: QuoteStep): { premium: number } => {
46	  const assessedPremium = withSurcharge(
47	    policyBasePremium(step.items),
48	    INITIAL_ASSESSMENT_SURCHARGE,
49	  );
50	
51	  return { premium: roundInMHPCOsFavour(assessedPremium + PROCESSING_FEE) };
52	};
53	
54	export const runScenario = (scenario: Scenario): ScenarioResults => ({
55	  results: scenario.steps.map(quote),
56	});
